// G7-06 canonical cross-format fixture payloads and SHA-256 manifest for G7-05 verification.
// Embedded as gzip+base64 so cloud-runner VMs (which only clone uniwork-office) and Prettier hooks
// never alter fixture bytes or hashes.
import { createHash } from 'node:crypto'
import { copyFileSync, existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import { join, resolve } from 'node:path'
import { gunzipSync } from 'node:zlib'

export const G7_06_FIXTURES = [
  {
    id: 'fx-xlsx-revenue-xyz',
    name: 'fx-xlsx-revenue-xyz.xlsx',
    ext: 'xlsx',
    bytes: 18806,
    sha256: 'a93cd768ca51347a1225e15fa002a2969a46f8dc465d189b7478cdd5a948b446',
    gzBase64:
      '',
  },
  {
    id: 'fx-docx-report-vi',
    name: 'fx-docx-report-vi.docx',
    ext: 'docx',
    bytes: 11187,
    sha256: '5e93b1dd7aefa0f8d816ccb7d5648b8bba4aa23eb5e95dbeddb3f045657c828c',
    gzBase64:
      '',
  },
  {
    id: 'fx-pptx-deck-vi',
    name: 'fx-pptx-deck-vi.pptx',
    ext: 'pptx',
    bytes: 25849,
    sha256: '958a8086fb3b1927319f88c12259e2f3c67b78a3f956ee0323f1c7631b2e2b20',
    gzBase64:
      '',
  },
  {
    id: 'fx-pdf-invoice-vi',
    name: 'fx-pdf-invoice-vi.pdf',
    ext: 'pdf',
    bytes: 99002,
    sha256: '17603fe876d45bfbd936cb03b9930a988e7842ab2c4d143763d76ae8ab253cdd',
    gzBase64:
      '',
  },
  {
    id: 'fx-md-notes-vi',
    name: 'fx-md-notes-vi.md',
    ext: 'md',
    bytes: 723,
    sha256: 'e09e98a5e41d78549054e53d29effc882547629076776f4c93a08f5331856def',
    gzBase64:
      '',
  },
  {
    id: 'fx-html-page-vi',
    name: 'fx-html-page-vi.html',
    ext: 'html',
    bytes: 955,
    sha256: 'e50b42f33ca5c560263d64f8c50022325abc067da525f26c18742065a7ebc884',
    gzBase64:
      '',
  },
]

export function sha256File(filePath) {
  const buf = readFileSync(filePath)
  return createHash('sha256').update(buf).digest('hex')
}

export function materializeFixtures(targetDir, options = {}) {
  const outDir = resolve(targetDir)
  mkdirSync(outDir, { recursive: true })
  const sourceDir = options.sourceDir || process.env.G7_05_FIXTURES_DIR || ''
  const results = []

  for (const fixture of G7_06_FIXTURES) {
    const destPath = join(outDir, fixture.name)
    const candidateSource = sourceDir ? join(resolve(sourceDir), fixture.name) : ''
    if (candidateSource && existsSync(candidateSource)) {
      copyFileSync(candidateSource, destPath)
    } else {
      const raw = gunzipSync(Buffer.from(fixture.gzBase64, 'base64'))
      writeFileSync(destPath, raw)
    }
    const actualSha = sha256File(destPath)
    const actualBytes = readFileSync(destPath).length
    if (!options.skipHashCheck && (actualSha !== fixture.sha256 || actualBytes !== fixture.bytes)) {
      throw new Error(
        `Fixture integrity check failed for ${fixture.name}: expected ${fixture.bytes}B/${fixture.sha256}, got ${actualBytes}B/${actualSha}`,
      )
    }
    results.push({
      id: fixture.id,
      name: fixture.name,
      ext: fixture.ext,
      path: destPath,
      bytes: actualBytes,
      sha256: actualSha,
    })
  }
  return results
}
